<template>
 <div class="page positions-page"><div class="page-head"><div><h2>权限管理</h2><p class="sub">按岗位直接配置模块与按钮权限，保存后即时生效</p></div><button class="btn" @click="showHistory=!showHistory">{{showHistory?'返回权限设置':'变更记录'}}</button></div>
 <p v-if="error" class="notice" role="alert">{{ error }}</p><p v-if="success" role="status">{{ success }}</p>
 <section v-if="showHistory" class="permission-panel"><h3>权限变更记录</h3><p class="sub">保存即生效，记录仅供追溯。</p><table class="data"><thead><tr><th>版本</th><th>操作</th><th>操作人</th><th>时间</th></tr></thead><tbody><tr v-for="(h,i) in state.audit" :key="i"><td>{{h.revision||'—'}}</td><td>{{{save:'保存岗位权限',members:'调整成员',delete:'删除岗位'}[h.action]||h.action}}</td><td>{{h.operator}}</td><td>{{$fmt(h.time)}}</td></tr><tr v-if="!state.audit?.length"><td colspan="4">暂无变更记录</td></tr></tbody></table></section>
 <div v-else class="positions-grid"><aside class="position-list"><div class="list-head"><strong>岗位列表</strong><button class="btn btn-primary" @click="create">＋ 新增岗位</button></div><input v-model="search" class="input" placeholder="搜索岗位" /><button v-for="p in filtered" :key="p.id" :class="['position-item',{selected:form.id===p.id}]" @click="choose(p)"><strong>{{ p.name }}</strong><small>{{ count(p.id) }} 人 · {{ (p.selected_perms||p.perms).length }} 项权限</small></button><p v-if="!filtered.length" class="sub">尚无岗位，点击新增开始配置</p></aside>
 <section class="permission-panel"><div class="panel-top"><div><h3>{{ form.id ? form.name : '新增岗位' }}</h3><span class="sub">{{ form.perms.length }} 项已选</span></div><div><button v-if="form.id" class="btn" :disabled="busy" @click="remove">删除岗位</button> <button class="btn btn-primary" :disabled="busy" @click="save">{{busy?'处理中…':'保存权限'}}</button></div></div>
 <div class="editor-fields"><label>岗位名称 <span class="req">*</span><input v-model="form.name" maxlength="40" class="input" placeholder="例如：品检主管" /></label></div>
 <p class="sub">勾选模块查看及所需按钮即可授权，新增、编辑、删除、停用、启用独立控制。无需复核签字。管理员专属操作仍由系统管理员执行。</p>
 <input v-model="filter" class="input permission-search" placeholder="搜索模块或权限" />
 <details v-for="g in groups" :key="g.key" class="permission-group" open><summary>{{g.label}}<span>{{g.items.filter(x=>form.perms.includes(x.code)).length}} / {{g.items.length}}</span></summary><div class="group-tools"><label><input type="checkbox" :checked="g.items.every(x=>form.perms.includes(x.code))" :indeterminate="g.items.some(x=>form.perms.includes(x.code))&&!g.items.every(x=>form.perms.includes(x.code))" @change="toggle(g,$event.target.checked)" /> 全选本组</label></div><div class="checks"><label v-for="item in g.items" :key="item.code" :class="['chip',{checked:form.perms.includes(item.code)}]" :title="item.code"><input type="checkbox" v-model="form.perms" :value="item.code" @change="permissionChanged(item,$event.target.checked)" />{{item.label}}</label></div></details>
 <section v-if="form.id" class="members"><h3>岗位成员</h3><p class="sub">分配到本岗位会替换该账号原有业务授权。移出后只保留本人自助权限，管理员账号不参与普通岗位分配。</p><input class="input" v-model="memberSearch" placeholder="搜索姓名 / 手机号" /><div class="checks"><label v-for="u in membersFiltered" :key="u.id" class="chip"><input type="checkbox" v-model="memberIds" :value="u.id" />{{u.name||u.username}} · {{u.username}}<small v-if="state.bindings[u.id]&&state.bindings[u.id]!==form.id">（其他岗位）</small></label></div><button class="btn btn-primary" :disabled="busy" @click="saveMembers">保存成员分配（{{memberIds.length}} 人）</button></section>
 </section></div></div>
</template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue';
import {api} from '../api';
const state=reactive({revision:0,positions:[],bindings:{},users:[],catalog:{roles:[],modules:[],permissions:[],actions:{}}}),form=reactive({id:null,name:'',roles:[],perms:[]});
const showHistory=ref(false);
const search=ref(''),filter=ref(''),memberSearch=ref(''),memberIds=ref([]),busy=ref(false),error=ref(''),success=ref('');
const names={"mindmap": "业务蓝图", "blueprint": "别名", "node-flow": "工序流程模板：节点可自定义", "files": "私有附件下载：登录态或带过期签名", "import": "CSV 批量导入", "price-tiers": "阶梯报价", "quotations": "报价单", "piece-wage": "计件工资", "statements": "客户对账单（对账函）", "credit": "客户信用", "payable": "应付台账", "cashflow": "资金计划", "payment-requests": "付款申请单（审批 → 出纳执行付款）", "collections": "催收", "exceptions": "异常协同与日清（六类归口 → 今日必办 → 认领/关闭/复核）", "prod-report": "生产交付效率与质量报表（准交/效率/质量/在制龄/计划偏差）", "flow-changes": "流程变更发布与审计（草稿→试运行→发布→回滚）", "privacy": "隐私审计", "skills": "技能矩阵与岗位资格（评定→矩阵→受限工序门禁→到期提醒）", "self": "本人自助", "customer-progress": "客户进度发布（三条路线 → 发布快照 → 撤回留版本）", "after-sales": "售后单（退款/实收/检验/再上架/追偿 五轨独立）", "statement-files": "对账资料（定版快照 → 授权 → 下载留痕）", "office-supply": "办公耗材与服务采购（申领→采购→验收→入库/转资产/入费用）", "custody": "资产领归", "admin-ops": "行政运营报表（宿舍/费用/饭卡/资产/耗材/预算/工单）", "payroll-check": "薪酬计件与工资核对（重算勾稽 + 差异登记调整单）", "exports": "数据导出与订阅（白名单数据集 / 水印 / 周期订阅）", "go-live": "上线检查清单（数据/权限/备份/财务/运行/组织 六大块）", "bad-debt": "坏账准备计提（按账龄差额补提/冲回，生成 6702/1231 凭证）", "payrolls": "薪酬", "assets": "固定资产", "admin-expenses": "行政费用", "mall": "客户商城", "mall-admin": "客户商城后台", "qc": "质量检验", "channel": "零售渠道", "confirm": "客户确认", "hr": "人事行政", "facility": "后勤管理", "finance": "往来账", "costing": "成本对象与已售毛利", "commitments": "接单评审与交期承诺", "requirements": "齐套与缺料看板", "cuts": "裁床排料与扎包", "first-articles": "首件确认与工位工艺", "receipts": "生产原料收货与检验", "mail": "内部邮件", "supplier-evals": "供应商评价与备用产能", "purchase-changes": "停单改量与供应商退料", "reworks": "返工报废", "production-close": "生产结单", "equipment": "设备管理", "kpi": "岗位绩效", "admin-contracts": "行政合同与履约日历", "process": "工序", "dq": "数据质量", "wh": "仓储", "gl": "总账", "spot": "现货分析", "ai": "智能助手", "budget": "预算", "bank": "银行", "group": "集团管理", "cockpit": "经营驾驶舱", "mkt": "营销", "org": "组织岗位", "tax": "税务", "crm": "客户销售", "supply": "供给预订", "notify": "手机通知", "whplan": "美仓作业", "schedule": "生产排程", "spotops": "现货经营", "labels": "扎标", "inspection": "验货报告", "photos": "现场照片", "backup": "备份与恢复", "access": "岗位权限复核", "importops": "数据导入", "orders": "销售订单", "customers": "客户档案", "products": "产品管理", "users": "系统账号", "techpacks": "开发管理", "costs": "成本审核", "samples": "样衣", "settings": "系统设置", "materials": "物料档案", "reports": "生产报工", "stock": "库存管理", "purchases": "采购管理", "suppliers": "供应商", "factories": "工厂管理", "dispatch": "生产分单", "employees": "员工档案", "crafts": "订单工序", "craft-types": "工序类别", "approvals": "审批中心", "order-nodes": "生产节点", "pre-orders": "预下单", "material-development": "面辅料开发", "pattern-flows": "打版流程", "sample-archives": "样衣库", "attachments": "附件", "upload": "图片上传", "dashboard": "工作台", "audit": "审计日志", "pricing": "价格费用池", "cost-objects": "成本对象", "integration": "外部接口", "order": "销售订单", "photo": "现场照片", "production": "生产管理", "node": "工序流程", "quote": "报价单", "development": "开发管理", "cost": "成本审核", "craft": "工序管理", "material": "物料档案", "report": "生产报工", "fa": "首件确认", "customer": "客户档案", "product": "产品管理", "factory": "工厂管理", "purchase": "采购管理", "supplier": "供应商", "receipt": "收料检验", "employee": "员工档案", "leave": "请假管理", "payroll": "薪酬核算", "piecewage": "计件工资", "admincontract": "行政合同", "asset": "固定资产", "expense": "行政费用", "pattern": "打版流程", "user": "系统账号", "baddebt": "坏账", "collection": "催收", "exception": "异常日清", "prodreport": "生产报表", "flowchange": "流程变更", "skill": "技能资格", "custprogress": "客户进度", "aftersale": "售后", "statementfile": "对账文件", "office": "办公耗材", "adminops": "行政运营", "paycheck": "工资核对", "export": "导出中心", "golive": "上线检查", "bankaccount": "银行账户", "contract": "合同", "paymentreq": "付款申请", "approvalflow": "审批流程", "segment": "主体对比", "matflow": "领退料", "investment": "长期投资", "cutdispatch": "裁片外发", "devmaster": "研发立项", "supreview": "供方复审"};

const filtered=computed(()=>state.positions.filter(p=>p.name.includes(search.value)));
const count=id=>Object.values(state.bindings).filter(x=>x===id).length;
const membersFiltered=computed(()=>state.users.filter(u=>u.role!=='admin'&&((u.name||'')+u.username).includes(memberSearch.value)));
const groups=computed(()=>{
 const result={};for(const m of state.catalog.modules)result[m]={key:m,label:names[m]||m,items:[{code:'module.'+m+'.read',label:'查看列表与详情'}]};
 for(const [m,items] of Object.entries(state.catalog.actions||{}))if(result[m])result[m].items.push(...items);
 const fieldModules={'hr.pii':'employees','crm.pii':'customers','supplier.pii':'suppliers','payroll.sensitive':'payrolls','adminops.detail':'admin-ops'};
 const fieldNames={'hr.pii':'查看员工敏感字段','crm.pii':'查看客户联系信息','supplier.pii':'查看供应商联系信息','payroll.sensitive':'查看工资明细','adminops.detail':'查看行政个人明细'};
 for(const p of state.catalog.field_permissions||[]){const m=fieldModules[p];if(result[m])result[m].items.push({code:p,label:fieldNames[p]||p});}
 return Object.values(result).filter(g=>!filter.value||g.label.includes(filter.value)||g.items.some(i=>(i.label+i.code).includes(filter.value)));
});
function editable(p){
 const fields=new Set(state.catalog.field_permissions||[]),codes=new Set([...(p.selected_perms||p.perms)].filter(c=>/^action\./.test(c)||/^module\.[^.]+\.read$/.test(c)||fields.has(c)));
 for(const code of [...codes])if(code.startsWith('action.'))codes.add('module.'+code.split('.')[1]+'.read');
 return [...codes];
}
function permissionChanged(item,on){
 if(on&&item.code.startsWith('action.')){const m=item.code.split('.')[1],read='module.'+m+'.read';if(!form.perms.includes(read))form.perms.push(read);}
 if(!on&&item.code.startsWith('module.')){const m=item.code.split('.')[1];form.perms=form.perms.filter(c=>!c.startsWith('action.'+m+'.'));}
}
function choose(p){if(dirty()&&!confirm('尚有未保存的权限修改，确定切换岗位？'))return;Object.assign(form,{id:p.id,name:p.name,roles:[...p.roles],perms:editable(p)});memberIds.value=state.users.filter(u=>state.bindings[u.id]===p.id).map(u=>u.id);error.value='';}
function dirty(){const p=state.positions.find(p=>p.id===form.id);return p?form.name!==p.name||JSON.stringify([...form.roles].sort())!==JSON.stringify([...p.roles].sort())||JSON.stringify([...form.perms].sort())!==JSON.stringify(editable(p).sort()):!!form.name;}
function create(){if(dirty()&&!confirm('放弃未保存的修改并新建岗位？'))return;Object.assign(form,{id:null,name:'',roles:[],perms:[]});memberIds.value=[];}
function toggle(g,on){const set=new Set(form.perms);g.items.forEach(i=>on?set.add(i.code):set.delete(i.code));form.perms=[...set];}
async function load(){try{Object.assign(state,await api.accessPositions());}catch(e){error.value=e.message;}}
async function mutate(body,message){busy.value=true;error.value='';success.value='';try{Object.assign(state,await api.saveAccessPositions({...body,revision:state.revision}));success.value=message;return true;}catch(e){error.value=e.message;if(e.status===409)await load();return false;}finally{busy.value=false;}}
async function save(){const name=form.name;if(await mutate({action:'save',id:form.id,name:form.name,perms:form.perms},'岗位权限已保存')){const p=state.positions.find(p=>p.name===name);Object.assign(form,{...p,roles:[...p.roles],perms:editable(p)});}}
async function remove(){if(!confirm('确认删除岗位“'+form.name+'”？有成员的岗位需先移出成员。'))return;if(await mutate({action:'delete',id:form.id},'岗位已删除'))Object.assign(form,{id:null,name:'',roles:[],perms:[]});}
async function saveMembers(){await mutate({action:'members',id:form.id,user_ids:memberIds.value},'成员分配已保存，后台授权已更新');}
onMounted(load);
</script>
<style scoped>
.positions-grid{display:grid;grid-template-columns:260px minmax(0,1fr);gap:20px;align-items:start}.position-list,.permission-panel{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:20px}.list-head,.panel-top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.position-list>.input{margin-bottom:12px}.position-item{display:flex;flex-direction:column;gap:8px;width:100%;text-align:left;border:0;border-radius:8px;background:transparent;color:var(--text);padding:14px;margin:4px 0;cursor:pointer}.position-item.selected{background:var(--brand-soft);box-shadow:inset 3px 0 var(--brand)}small,.sub{color:var(--text-muted)}.editor-fields{display:grid;grid-template-columns:minmax(220px,420px);gap:20px;margin-bottom:16px}.editor-fields input.input{margin-top:8px}fieldset{border:1px solid var(--border);border-radius:8px}.chip{display:inline-flex;align-items:center;gap:7px;padding:9px 12px;border:1px solid var(--border);border-radius:6px;color:var(--text);font-size:13px;cursor:pointer}.chip.checked{border-color:var(--brand);background:var(--brand-soft);color:var(--brand)}input[type=checkbox]{accent-color:var(--brand)}.checks{display:flex;flex-wrap:wrap;gap:10px;padding:14px}.permission-group{border:1px solid var(--border);border-radius:8px;margin:12px 0;overflow:hidden}.permission-group summary{padding:14px;background:var(--surface-2);font-weight:600;cursor:pointer}.permission-group summary span{float:right;font-size:12px;color:var(--text-muted)}.group-tools{padding:12px 14px 0;font-size:13px}.members{border-top:1px solid var(--border);margin-top:24px;padding-top:24px}.notice{color:var(--danger)}.req{color:var(--danger)}.permission-search{max-width:420px}@media(max-width:900px){.positions-grid,.editor-fields{grid-template-columns:1fr}.position-list{max-height:300px;overflow:auto}.panel-top{flex-wrap:wrap}}
</style>
